<script setup lang="ts">
import {previewPrint} from './printPreview';
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import {api,can,type Configuration,type WirelessTaskRecord,type WirelessStage} from './api';
const props=defineProps<{licensed:boolean;config:Configuration;canOperate:boolean;dirty:boolean;focusTank?:string}>();
const stages:Record<WirelessStage,string>={Queued:'排队等待',Checking:'启动检查',Authorizing:'本任务认证',EnteringMeasureI:'进入测量Ⅰ',InitialStability:'起始稳定观察',InitialDwell:'起始停留10分钟',Planning:'冻结液面与规划',Descending:'下降至测点',Stopping:'请求停止',Settling:'核验实际停稳',PointDwell:'测点停留10分钟',ReadingTemperature:'读取并保存测点',RestoringMeasureI:'恢复测量Ⅰ',Completed:'流程完成',Skipped:'液面过低 · 未测量',Failed:'未执行 / 失败',Cancelled:'已取消',RequiresReview:'中断 · 需人工核查',Reviewed:'人工核查已记录'};
const tankId=ref(props.focusTank||''),points=ref(5),rows=ref<WirelessTaskRecord[]>([]),detail=ref<WirelessTaskRecord|null>(null),error=ref(''),message=ref(''),busy=ref(false),confirmed=ref(false),reason=ref(''),mode=ref<'start'|'cancel'|'review'|null>(null),subject=ref<WirelessTaskRecord|null>(null),support=ref<{supported:boolean;reason:string|null}|null>(null),start=ref(''),end=ref(''),state=ref('all');
let timer:ReturnType<typeof setInterval>|undefined,loading=false,protocol='';
const tanks=computed(()=>props.config.tanks.filter(t=>t.temperatureMode==='Wireless'));
const selected=computed(()=>tanks.value.find(t=>t.id===tankId.value));
const filtered=computed(()=>rows.value.filter(r=>(state.value==='all'||state.value==='active'?state.value==='all'||r.holdsTank:r.stage===state.value)&&(!start.value||Date.parse(r.createdAtUtc)>=new Date(start.value).getTime())&&(!end.value||Date.parse(r.createdAtUtc)<=new Date(end.value).getTime())));
const hasPending=computed(()=>rows.value.some(r=>r.holdsTank));
const date=(s:string|null|undefined)=>s?new Date(s).toLocaleString('zh-CN',{hour12:false}):'—';
async function load(){if(loading)return;loading=true;try{rows.value=await api('/api/wireless-tasks'+(tankId.value?'?tank='+tankId.value:''));if(detail.value)detail.value=rows.value.find(r=>r.id===detail.value!.id)||null;const p=props.config.channels.find(c=>c.id===selected.value?.channelId)?.protocol||'';if(p!==protocol){protocol=p;support.value=p?await api('/api/wireless-support?protocol='+p):null}}catch(e){error.value=String(e)}finally{loading=false}}
function open(next:'start'|'cancel'|'review',r?:WirelessTaskRecord){if(props.dirty){error.value='请先保存或重新载入待保存配置';return}if(next==='start'&&!props.licensed){error.value='当前授权不允许新建测温任务';return}mode.value=next;subject.value=r||null;confirmed.value=false;reason.value='';error.value=''}
async function submit(){if(!mode.value||busy.value)return;busy.value=true;try{if(mode.value==='start')await api('/api/tanks/'+tankId.value+'/wireless-tasks','POST',{configurationRevision:props.config.revision,points:points.value,confirmed:confirmed.value});else await api('/api/wireless-tasks/'+subject.value!.id+'/'+mode.value,'POST',{confirmed:confirmed.value,reason:reason.value});message.value=mode.value==='start'?'任务已受理。同一采集通道按队列执行，程序退出后不会自动续跑。':mode.value==='cancel'?'后续测温已取消并请求停止，请核对实际位置、模式和运动情况。':'人工核查结论已记录，未重放原任务。';mode.value=null;await load()}catch(e){error.value=String(e)}finally{busy.value=false}}
function printRows(){if(!props.licensed||!can('DataExport'))return;previewPrint({title:'平均温度测量记录',readPermission:'HistoryRead',scope:['当前筛选 '+filtered.value.length+' 条任务；成功、失败和中断结果分别保留。','起始 '+(start.value||'不限')+' · 结束 '+(end.value||'不限')],sections:[{title:'任务记录',headers:['储罐','开始时间','完成时间','结果','冻结液面X mm','有效M / 计划N','平均 ℃','恢复测量Ⅰ','说明'],rows:filtered.value.map(r=>[r.target.tank.code,date(r.createdAtUtc),date(r.finishedAtUtc),stages[r.stage],r.plan?.surfaceMm,r.validPoints+' / '+(r.plan?.plannedPoints??'—'),r.hasSuccessfulResult?r.averageTemperature.value:null,r.measureIRestored?'是':'否',r.message])}]})}
function printTask(){if(!props.licensed||!can('DataExport')||!detail.value)return;const r=detail.value;previewPrint({title:r.target.tank.code+' · 平均测温任务明细',readPermission:'HistoryRead',scope:['任务 '+r.id+' · '+stages[r.stage],date(r.createdAtUtc)+' 至 '+date(r.finishedAtUtc),'有效点 '+r.validPoints+' / '+(r.plan?.plannedPoints??'—')+' · 平均 '+(r.hasSuccessfulResult?r.averageTemperature.value:'—')+' ℃ · '+r.message],sections:[{title:'逐点测量',headers:['点号','目标H mm','停止后P mm','停留开始','实际停留秒','读取时间','温度 ℃','状态 / 原因'],rows:r.points.map(p=>[p.number,p.targetMm,p.stoppedPositionMm,date(p.dwellStartedAtUtc),p.dwellElapsedSeconds,date(p.sampledAtUtc),p.temperature.quality==='Good'?p.temperature.value:null,p.temperature.reason||p.temperature.quality])}]})}
function exportRows(){if(!props.licensed||!can('DataExport'))return;const data:unknown[][]=[['任务编号','储罐','协议','开始时间','完成时间','任务状态','冻结液面X mm','计划N','有效M','点序','目标H mm','实际停止P mm','停留开始','实际停留秒','读取时间','温度 ℃','温度状态','读取次数','原始温度字','任务平均 ℃','已恢复测量Ⅰ','原因']];for(const r of filtered.value)for(const p of r.points.length?r.points:[null])data.push([r.id,r.target.tank.code,r.target.channel.protocol,date(r.createdAtUtc),date(r.finishedAtUtc),stages[r.stage],r.plan?.surfaceMm,r.plan?.plannedPoints,r.validPoints,p?.number,p?.targetMm,p?.stoppedPositionMm,date(p?.dwellStartedAtUtc),p?.dwellElapsedSeconds,date(p?.sampledAtUtc),p?.temperature.value,p?.temperature.reason||p?.temperature.quality,p?.attempts,p?.rawTemperature,r.hasSuccessfulResult?r.averageTemperature.value:null,r.measureIRestored?'是':'否',r.message]);window.LocalWorkbook.download('平均温度测量记录',[{name:'平均温度测量记录',rows:data}])}
watch(()=>props.focusTank,id=>{tankId.value=id||''});watch(tankId,()=>void load());onMounted(()=>{void load();timer=setInterval(()=>void load(),2000)});onUnmounted(()=>{if(timer)clearInterval(timer)});
</script>
<template><section class="wireless-tasks"><div class="toolbar"><h2>平均温度测量</h2><button class="button" :disabled="!licensed||!can('DataExport')||!filtered.length" @click="printRows">打印记录预览</button><button class="button" :disabled="!licensed||!can('DataExport')||!filtered.length" @click="exportRows">导出当前记录 Excel</button></div><div class="panel panel-body"><div class="config-fields"><label class="config-field">储罐<select aria-label="测温储罐" v-model="tankId" :disabled="!!focusTank"><option value="">全部无线浮子储罐</option><option v-for="t in tanks" :key="t.id" :value="t.id">{{t.code}}</option></select></label><label class="config-field">本次选择点数<select aria-label="本次测温点数" v-model.number="points"><option v-for="i in 16" :key="i" :value="i">{{i}}点</option></select></label></div><p class="help">实际点数按冻结液面高度调整。起始稳定后停留10分钟，每点停稳到位后再停留10分钟；起始温度不参与平均。默认5点仅停留合计60分钟，另加稳定、移动和恢复时间。</p><p v-if="support&&!support.supported" class="notice">{{support.reason}}</p><p v-else-if="selected&&!selected.controls.wirelessMeasurementEnabled" class="notice">本罐尚未启用平均测温，请由管理员在储罐配置中开启。</p><button v-if="can('AverageTemperatureStart')" class="button primary" :disabled="!licensed||!selected||!selected.controls.wirelessMeasurementEnabled||!support?.supported||hasPending||busy" @click="open('start')">新建测温任务</button></div><p v-if="error&&!mode" role="alert" class="error-message">{{error}}</p><p v-if="message" role="status" class="notice">{{message}}</p><div class="panel query-panel"><div class="query-fields"><label class="config-field">状态<select v-model="state"><option value="all">全部状态</option><option value="active">执行中或待核查</option><option v-for="(name,key) in stages" :key="key" :value="key">{{name}}</option></select></label><label class="config-field">开始时间<input v-model="start" type="datetime-local"></label><label class="config-field">结束时间<input v-model="end" type="datetime-local"></label></div></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>储罐 / 开始时间</th><th>当前阶段</th><th>进度 / 有效点</th><th>本次平均温度</th><th>完成时间</th><th>操作</th></tr></thead><tbody><tr v-for="r in filtered" :key="r.id"><td>{{r.target.tank.code}}<small>{{date(r.createdAtUtc)}}</small></td><td>{{stages[r.stage]}}<small>{{r.message}}</small><small v-if="r.displayDueAtUtc">预计到时 {{date(r.displayDueAtUtc)}}（实际停留按单调计时）</small></td><td>{{r.currentPoint}} / {{r.plan?.plannedPoints??'待规划'}}<small>有效 {{r.validPoints}} · 最少要求 {{r.plan?.requiredValidPoints??'—'}}</small></td><td>{{r.hasSuccessfulResult?r.averageTemperature.value?.toFixed(2)+' ℃':'—'}}</td><td>{{date(r.finishedAtUtc)}}</td><td><button class="text-button" @click="detail=r">点明细</button><button v-if="can('InstrumentStop')&&r.holdsTank&&r.stage!=='RequiresReview'" class="text-button" @click="open('cancel',r)">取消后续并停止</button><button v-if="can('ControlReview')&&r.stage==='RequiresReview'" class="text-button" @click="open('review',r)">人工核查</button></td></tr><tr v-if="!filtered.length"><td colspan="6" class="empty">暂无符合条件的测温任务</td></tr></tbody></table></div><p class="table-foot">最多显示最近1000项任务；旧成功结果单独保留，进行中或失败任务不覆盖。</p></section><section v-if="detail" class="panel panel-body"><div class="toolbar"><h3>{{detail.target.tank.code}} · 测点明细</h3><div class="inline-actions"><button class="button" :disabled="!licensed||!can('DataExport')" @click="printTask">打印明细预览</button><button class="button" @click="detail=null">收起</button></div></div><p class="help">任务 {{detail.id}} · {{detail.ruleVersion}}<br>冻结液面X {{detail.plan?.surfaceMm??'—'}} mm · {{date(detail.planFrozenAtUtc)}} · 起始基准温度 {{detail.baselineTemperature.value??'—'}} ℃（不计入平均）<br>恢复测量Ⅰ：{{detail.measureIRestored?'已确认':'未确认'}} · {{detail.message}}</p><div class="table-wrap"><table><thead><tr><th>点序</th><th>目标H mm</th><th>停止后P mm</th><th>偏差 mm</th><th>停留开始</th><th>实际停留 秒</th><th>读取时间</th><th>温度 ℃</th><th>读取次数 / 说明</th></tr></thead><tbody><tr v-for="p in detail.points" :key="p.number"><td>{{p.number}}</td><td>{{p.targetMm}}</td><td>{{p.stoppedPositionMm??'—'}}</td><td>{{p.stoppedPositionMm===null?'—':(p.stoppedPositionMm-p.targetMm).toFixed(1)}}</td><td>{{date(p.dwellStartedAtUtc)}}</td><td>{{p.dwellElapsedSeconds.toFixed(0)}}</td><td>{{date(p.sampledAtUtc)}}</td><td>{{p.temperature.quality==='Good'?p.temperature.value?.toFixed(2):'—'}}</td><td>{{p.attempts}} · {{p.temperature.reason||'有效'}}</td></tr></tbody></table></div></section></section><div v-if="mode" class="modal-backdrop"><section class="modal" role="dialog" aria-label="确认平均测温操作"><div class="modal-head"><h2>{{mode==='start'?'新建平均测温任务':mode==='cancel'?'取消后续测温并请求停止':'人工核查测温任务'}}</h2><button class="button" @click="mode=null">关闭</button></div><form class="modal-body" @submit.prevent="submit"><p v-if="error" class="error-message" role="alert">{{error}}</p><p class="notice">{{mode==='start'?selected?.code:subject?.target.tank.code}} · {{mode==='start'?'将操作本罐浮子下降、停止和恢复测量Ⅰ；须确认现场允许自动测温。':mode==='cancel'?'取消后续测温并发送独立停止；回读确认不能代替实际机械停稳。':'核对实际位置、运动、仪表模式及原操作。保存只解除本次任务待核查状态，不重放测温或自动恢复。'}}</p><label v-if="mode==='review'" class="config-field">现场核查结论<textarea v-model="reason" required maxlength="1000" rows="4"></textarea></label><label class="checkbox"><input v-model="confirmed" type="checkbox" required>已核对本罐设备、现场状态及本次操作，确认执行</label><button class="button primary" :disabled="!confirmed||busy||(mode==='review'&&!reason.trim())">{{mode==='start'?'确认启动任务':mode==='cancel'?'确认取消并请求停止':'保存核查结论'}}</button></form></section></div></template>
